<?php declare(strict_types=1);
use Kulturhus\Verein\{BalanceClosingCorrections,BalanceClosingCorrection,BalanceLedger,BoardAccess,Permissions,Settings,TaxCatalog};
require_once __DIR__.'/../../../src/Finance/Balance/BalanceClosingCorrections.php';
$closingMessages=$managerLanguageMessages??[];
$closingText=static fn(string $source):string=>$closingMessages!==[]?\Kulturhus\Native\Language\BalanceFilingMessages::text($source,$closingMessages):$source;
if(array_key_exists('correction_original',$_GET)){require __DIR__.'/balance-closing-original.php';return;}
try{$correctionState=(new BalanceClosingCorrections($db,(string)$_SESSION['actor']))->get($year);}catch(DomainException $ex){echo '<p role="alert">'.e($closingText($ex->getMessage())).'</p>';return;}
$canCorrect=BalanceLedger::enabled()&&Permissions::actor($db,(string)$_SESSION['actor'])['finance_access']==='write'&&((new Settings($db,(string)$_SESSION['actor']))->section('tax')['data']['accounting_basis']??'euer')==='balance';
$submitted=($_SERVER['REQUEST_METHOD']==='POST'&&(int)input($_POST,'balance_year')===$year)?$_POST:[];
$old=input($submitted,'action')==='balance-correction-save'?$submitted:[];
$submittedNote=static fn(string $action):string=>input($submitted,'action')===$action?input($submitted,'note'):'';
$submittedReviewed=static fn(string $action):bool=>input($submitted,'action')===$action&&input($submitted,'reviewed')==='1';
$proof=$correctionState['draft'];$base=$correctionState['report'];$last=$proof['input']??[];
$draftEntry=$last['entries'][0]??[];
$money=static fn(int $v):string=>number_format($v/100,2,',','.').' €';
$correctionHidden=static function(string $action)use($submitted,$year,$correctionState,$base):string{$same=input($submitted,'action')===$action;return csrf().hidden('balance_year',(string)$year).hidden('correction_revision',$same?input($submitted,'correction_revision'):(string)$correctionState['version']).hidden('base_hash',$same?input($submitted,'base_hash'):$base['closed_sha256']).hidden('action',$action);};
?>
<link rel="stylesheet" href="tax-guided.css?v=1"><div class="content" data-tax-guided>
<div class="page-heading"><h1><?= e($closingText('Jahresabschluss berichtigen')) ?> · <?= $year ?></h1><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year])) ?>"><?= e($closingText('Zum Jahresabschluss')) ?></a></div>
<section class="card"><p><?= e($closingText('Der ursprüngliche Abschluss bleibt erhalten. Die Buchhaltung bereitet die Korrektur vor; der Vorstand prüft und bestätigt sie. Es erfolgt keine Steuerabgabe.')) ?></p>
<p><strong><?= e($closingText($proof!==null?'Korrektur zur Prüfung vorbereitet':($correctionState['current']?'Bestätigter Abschluss':'Vorjahresabgleich oder erneute Prüfung erforderlich'))) ?></strong></p>
<?php if(!$correctionState['carry_current']): ?><p role="alert"><?= e($closingText('Das Vorjahr wurde berichtigt. Seine Anfangsbestände müssen neu übernommen werden.')) ?></p><?php endif ?>
<p><?= e($closingText('Ergebnis bisher:')) ?> <?= $money($base['calculation']['annual_result_cents']) ?><?php if($proof!==null): ?> · <?= e($closingText('Nach Korrektur:')) ?> <?= $money($proof['calculation']['annual_result_cents']) ?><?php endif ?></p></section>
<?php if($canCorrect&&$proof===null&&!$correctionState['current']&&$correctionState['carry_current']&&isset($base['correction'])&&BoardAccess::allowed($db,(string)$_SESSION['actor'])): ?><form method="post" class="card"><?= $correctionHidden('balance-correction-reaffirm') ?><h2><?= e($closingText('Abschluss erneut prüfen')) ?></h2><p><?= e($closingText('Die bisherige Freigabe ist nicht mehr aktuell. Die Abschlusswerte bleiben unverändert.')) ?></p><label><?= e($closingText('Prüfvermerk')) ?><input class="form-control" name="note" value="<?= e($submittedNote('balance-correction-reaffirm')) ?>" maxlength="1000" required></label><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" required <?= $submittedReviewed('balance-correction-reaffirm')?'checked':'' ?>><?= e($closingText('Den Korrekturabschluss und seine Nachweise vollständig geprüft.')) ?></label><button class="btn btn-solid theme-primary"><?= e($closingText('Unveränderten Abschluss bestätigen')) ?></button></form><?php endif ?>
<?php if($proof!==null): ?><section class="card"><h2><?= e($closingText('Änderungen prüfen')) ?></h2><p><?= e($proof['input']['reason']) ?></p><p><?= e($proof['input']['legal_basis']) ?></p>
<?php foreach($proof['deltas'] as $id=>$change):$sign=in_array($base['accounts'][$id]['group'],['equity','reserves','provisions','liabilities','member_payables','deferred','revenue'],true)?-1:1; ?>
<article><h3><?= e($base['accounts'][$id]['name']) ?></h3><?php if($change['opening_before_cents']!==$change['opening_after_cents']): ?><p><?= e($closingText('Jahresanfang:')) ?> <?= $money($sign*$change['opening_before_cents']) ?> → <?= $money($sign*$change['opening_after_cents']) ?></p><?php endif ?><p><?= e($closingText('Jahresende:')) ?> <?= $money($sign*$change['closing_before_cents']) ?> → <?= $money($sign*$change['closing_after_cents']) ?></p></article><?php endforeach ?>
<?php foreach($proof['input']['entries'] as $entry): ?><details><summary><?= e($entry['date'].' · '.$entry['description']) ?></summary><p><?= e($entry['evidence']) ?></p><?php foreach($entry['lines'] as $line): ?><p><?= e($base['accounts'][$line['account']]['name']) ?> · <?= e($closingText('Soll')) ?> <?= $money($line['debit_cents']) ?> · <?= e($closingText('Haben')) ?> <?= $money($line['credit_cents']) ?><?= $line['sphere']!==''?' · '.e($closingText(TaxCatalog::SPHERES[$line['sphere']])):'' ?></p><?php endforeach ?></details><?php endforeach ?>
<?php if($canCorrect&&BoardAccess::allowed($db,(string)$_SESSION['actor'])): ?><form method="post"><?= $correctionHidden('balance-correction-confirm').hidden('proof_hash',input($submitted,'action')==='balance-correction-confirm'?input($submitted,'proof_hash'):$proof['sha256']) ?><label><?= e($closingText('Prüfvermerk')) ?><input class="form-control" name="note" value="<?= e($submittedNote('balance-correction-confirm')) ?>" maxlength="1000" required></label><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" required <?= $submittedReviewed('balance-correction-confirm')?'checked':'' ?>><?= e($closingText('Grund, Belege, Beträge, Vorjahreswerte und steuerliche Zulässigkeit geprüft.')) ?></label><button class="btn btn-solid theme-primary"><?= e($closingText('Korrekturabschluss bestätigen')) ?></button></form><?php endif ?>
<?php if($canCorrect): ?><details><summary><?= e($closingText('Entwurf verwerfen')) ?></summary><form method="post"><?= $correctionHidden('balance-correction-discard') ?><label><?= e($closingText('Grund')) ?><input class="form-control" name="note" value="<?= e($submittedNote('balance-correction-discard')) ?>" maxlength="1000" required></label><button class="btn btn-outline theme-secondary secondary"><?= e($closingText('Entwurf verwerfen')) ?></button></form></details><?php endif ?></section><?php endif ?>
<?php if($canCorrect&&count($last['entries']??[])<=1): ?><details class="card" <?= $old?'open':'' ?>><summary><?= e($closingText($proof?'Korrekturentwurf ändern':'Korrektur vorbereiten · Buchhaltungsdetails')) ?></summary><form method="post">
<?= $correctionHidden('balance-correction-save').hidden('request_key',input($old,'request_key',$draftEntry['id']??bin2hex(random_bytes(16)))) ?>
<label><?= e($closingText('Was soll korrigiert werden?')) ?><select class="form-control" name="correction_kind"><?php foreach(BalanceClosingCorrection::KINDS as $id=>$label): ?><option value="<?= e($id) ?>" <?= input($old,'correction_kind',$last['kind']??'error')===$id?'selected':'' ?>><?= e($closingText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($closingText('Grund')) ?><textarea class="form-control" name="reason" maxlength="1000" required><?= e(input($old,'reason',$last['reason']??'')) ?></textarea></label>
<label><?= e($closingText('Nachweis der steuerlichen Zulässigkeit')) ?><textarea class="form-control" name="legal_basis" maxlength="1000" required><?= e(input($old,'legal_basis',$last['legal_basis']??'')) ?></textarea></label>
<p><?= e($closingText('Beim reinen Vorjahresabgleich bleiben die folgenden Buchungsfelder leer.')) ?></p>
<label><?= e($closingText('Buchungsdatum')) ?><input class="form-control" type="date" name="booked_on" min="<?= $year ?>-01-01" max="<?= $year ?>-12-31" value="<?= e(input($old,'booked_on',$draftEntry['date']??'')) ?>"></label>
<label><?= e($closingText('Vorgang')) ?><input class="form-control" name="description" maxlength="1000" value="<?= e(input($old,'description',$draftEntry['description']??'')) ?>"></label><label><?= e($closingText('Beleg / Nachweis')) ?><input class="form-control" name="evidence" maxlength="1000" value="<?= e(input($old,'evidence',$draftEntry['evidence']??'')) ?>"></label>
<?php for($i=0;$i<max(4,count($draftEntry['lines']??[]));$i++):$line=$draftEntry['lines'][$i]??null;$row=is_array($old['lines'][$i]??null)?$old['lines'][$i]:($old?[]:($line?['account'=>$line['account'],'debit'=>number_format($line['debit_cents']/100,2,',',''),'credit'=>number_format($line['credit_cents']/100,2,',',''),'sphere'=>$line['sphere']]:[])); ?><fieldset><legend><?= e($closingText('Zeile')) ?> <?= $i+1 ?></legend><label><?= e($closingText('Konto')) ?><select class="form-control" name="lines[<?= $i ?>][account]"><option value=""><?= e($closingText('Nicht verwendet')) ?></option><?php foreach($base['accounts'] as $id=>$a): ?><option value="<?= e($id) ?>" <?= input($row,'account')===$id?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach ?></select></label><div class="form-grid"><label><?= e($closingText('Soll · EUR')) ?><input class="form-control" name="lines[<?= $i ?>][debit]" inputmode="decimal" value="<?= e(input($row,'debit')) ?>"></label><label><?= e($closingText('Haben · EUR')) ?><input class="form-control" name="lines[<?= $i ?>][credit]" inputmode="decimal" value="<?= e(input($row,'credit')) ?>"></label></div><label><?= e($closingText('Vereinsbereich')) ?><select class="form-control" name="lines[<?= $i ?>][sphere]"><option value=""><?= e($closingText('Keiner · Bestandskonto')) ?></option><?php foreach(TaxCatalog::SPHERES as $id=>$label):if((string)$id==='9')continue; ?><option value="<?= e($id) ?>" <?= input($row,'sphere')===(string)$id?'selected':'' ?>><?= e($closingText($label)) ?></option><?php endforeach ?></select></label></fieldset><?php endfor ?>
<label class="check"><input class="check" type="checkbox" name="confirmed" value="1" required <?= input($old,'confirmed')==='1'?'checked':'' ?>><?= e($closingText('Zulässigkeit der Berichtigung bzw. Änderung und ihre Belege geprüft.')) ?></label><button class="btn btn-solid theme-primary"><?= e($closingText('Änderungen zur Prüfung vorbereiten')) ?></button></form></details><?php endif ?>
<?php if($correctionState['history']): ?><details class="card"><summary><?= e($closingText('Bisherige Korrekturstände')) ?></summary><?php foreach($correctionState['history'] as $h): ?><p><?= e((new DateTimeImmutable($h['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$closingText(match($h['state']){'draft'=>'Vorbereitet','reviewed'=>'Bestätigt','discarded'=>'Verworfen','reaffirmed'=>'Erneut bestätigt'}).' · '.$h['note']) ?></p><p><a class="btn btn-outline" data-balance-correction-history="<?= (int)$h['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'corrections'=>'1','correction_original'=>(string)$h['revision'],'correction_sha256'=>$h['sha256']])) ?>"><?= e($closingText('Diesen ursprünglichen Ausgang lesen')) ?></a></p><?php endforeach ?></details><?php endif ?>
</div>
